int tipc_nl_media_dump ( struct sk_buff * skb , struct netlink_callback * cb ) { int err ; int i = cb -> args [ 0 ] ; struct tipc_nl_msg msg ; msg . skb = skb ; msg . portid = NETLINK_CB ( cb -> skb ) . portid ; msg . seq = cb -> nlh -> nlmsg_seq ; rtnl_lock ( ) ; for ( ; media_info_array [ i ] != NULL ; i ++ ) { err = __tipc_nl_add_media ( & msg , media_info_array [ i ] , NLM_F_MULTI ) ; if ( err ) { break ; } } rtnl_unlock ( ) ; cb -> args [ 0 ] = i ; return skb -> len ; } 